def priority(item: float, bins: np.ndarray) -> np.ndarray:
    feasible = bins >= item
    new_remaining = bins - item
    feasible_remaining = new_remaining[feasible]
    if len(feasible_remaining) == 0:
        return np.zeros_like(bins)
    target = np.mean(feasible_remaining)
    priority_scores = -np.abs(new_remaining - target)
    return np.where(feasible, priority_scores, 0)
